const raw = $input.first().json;
const body = raw.body || raw;

const action = body.action || '';
const isPRWebhook = Boolean(body.pull_request);
const isCommentOnPR = Boolean(body.issue && body.comment);

const prNumber = body.pull_request?.number || body.issue?.number || body.number || '';
const repoFullName = body.repository?.full_name || body.pull_request?.base?.repo?.full_name || 'alex-asd0/ITMOv2';
const commentBody = (body.comment?.body || '').trim();

let route = 'ignore';
if (isCommentOnPR && action === 'created') {
  if (commentBody.includes('/make_other_ai_review')) {
    route = 'other_review';
  } else if (commentBody.includes('/make_ai_review')) {
    route = 'main_review';
  }
} else if (isPRWebhook && action === 'opened') {
  route = 'main_review';
}

return [{
  json: {
    route,
    pr_number: String(prNumber),
    repo_full_name: repoFullName,
    action,
    comment_body: commentBody
  }
}];

const rawDiff = $input.first().json.data || '';
const lines = rawDiff.split('\n');
const blocks = [];

let currentFile = null;
let currentHunkItems = []; // храним { text, rightLine, isAddition }
let newLineNum = 0;

const ignoreFiles = ['package-lock.json', 'yarn.lock', 'poetry.lock', 'pnpm-lock.yaml'];
const CHUNK_SIZE = 35; // комфортный размер блока без потери контекста

function flushHunk() {
  if (
    !currentFile ||
    ignoreFiles.some(f => currentFile.endsWith(f)) ||
    !currentHunkItems.some(i => i.isChange)
  ) {
    currentHunkItems = [];
    return;
  }

  // Если блок большой, делим его на связанные части (Part 1/N, Part 2/N), ничего не выбрасывая
  const totalParts = Math.ceil(currentHunkItems.length / CHUNK_SIZE);

  for (let p = 0; p < totalParts; p++) {
    const slice = currentHunkItems.slice(p * CHUNK_SIZE, (p + 1) * CHUNK_SIZE);

    // Ищем лучшую строку для привязки комментария в этой части
    const lastAdded = [...slice].reverse().find(i => i.isAddition && i.rightLine);
    const anyRight = slice.find(i => i.rightLine);
    const targetLine = lastAdded?.rightLine || anyRight?.rightLine;

    if (!targetLine) continue;

    const id = blocks.length;
    const partNote = totalParts > 1
      ? ` (PART ${p + 1}/${totalParts}${p + 1 < totalParts ? ' — продолжение в следующем BLOCK' : ' — продолжение предыдущего BLOCK'})`
      : '';

    blocks.push({
      id,
      path: currentFile,
      line: targetLine,
      side: 'RIGHT',
      part_note: partNote,
      snippet: slice.map(i => i.text).join('\n')
    });
  }

  currentHunkItems = [];
}

for (const line of lines) {
  if (line.startsWith('diff --git ')) {
    flushHunk();
    currentFile = null;
    continue;
  }
  if (line.startsWith('+++ b/')) {
    currentFile = line.slice(6).trim();
    continue;
  }
  if (line.startsWith('+++ /dev/null')) {
    currentFile = null;
    continue;
  }
  const hunkMatch = line.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)/);
  if (hunkMatch) {
    flushHunk();
    newLineNum = parseInt(hunkMatch[1], 10);
    currentHunkItems.push({ text: line, rightLine: newLineNum, isAddition: false, isChange: false });
    continue;
  }
  if (currentFile && currentHunkItems.length > 0) {
    if (line.startsWith('+') && !line.startsWith('+++')) {
      currentHunkItems.push({ text: `${newLineNum}: ${line}`, rightLine: newLineNum, isAddition: true, isChange: true });
      newLineNum++;
    } else if (line.startsWith('-') && !line.startsWith('---')) {
      currentHunkItems.push({ text: `   ${line}`, rightLine: null, isAddition: false, isChange: true });
    } else if (line.startsWith(' ')) {
      currentHunkItems.push({ text: `${newLineNum}: ${line}`, rightLine: newLineNum, isAddition: false, isChange: false });
      newLineNum++;
    }
  }
}
flushHunk();

const batchedPromptText = blocks
  .map(b => `=== [BLOCK_${b.id}] FILE: ${b.path}${b.part_note} | COMMENT_LINE: ${b.line} ===\n${b.snippet}\n=== [END_BLOCK_${b.id}] ===`)
  .join('\n\n');

return [{
  json: {
    blocks,
    batched_diff: batchedPromptText,
    model_label: 'Main Model (openai/gpt-5.2)'
  }
}];

