// Function (n8n) — общая нода для сборки комментариев GitHub из ответа модели
// Вход: $input.first().json.output — сырой вывод модели (строка)
// Источник blocks/model_label: любой из узлов парсинга (Main/Other/общий), выбирается автоматически

// Получение сырого ответа модели
const rawOutput = ($input.first().json.output || $json.output || '').trim();

// Утилита: безопасно получить json узла по имени
function getNodeJson(name) {
  try {
    const node = $(name).first();
    return node ? node.json : null;
  } catch (e) {
    return null;
  }
}

// Пытаемся найти любой доступный парсер диффа
const candidates = [
  'Parse Diff to Blocks (Main)',
  'Parse Diff to Blocks (Other)',
  'Parse Diff to Blocks'
];

let parsedNode = null;
for (const name of candidates) {
  const n = getNodeJson(name);
  if (n && Array.isArray(n.blocks)) {
    parsedNode = n;
    break;
  }
}

// Если не нашли — fallback на пустые значения
const blocks = Array.isArray(parsedNode?.blocks) ? parsedNode.blocks : [];

// label модели: предпочитаем значение из текущего item, затем из парсера, затем дефолт
const modelLabel = $json.model_label || parsedNode?.model_label || 'Clever Model';

// Попытка вытащить JSON-массив из ответа модели
let parsedArray = [];
try {
  const jsonMatch = rawOutput.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    parsedArray = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  parsedArray = [];
}

function toNum(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

// Уникализация комментариев по (path,line,body), чтобы избежать дублей
const seen = new Set();
function pushUnique(arr, item) {
  const key = `${item.path}|${item.line}|${item.body}`;
  if (!seen.has(key)) {
    seen.add(key);
    arr.push(item);
  }
}

// Маленькая валидация номера строки: если модель не указала line — fallback на b.line
function resolveLine(b, itemLine) {
  const ln = toNum(itemLine);
  if (ln != null) return ln;
  return toNum(b?.line);
}

const comments = [];
if (Array.isArray(parsedArray) && parsedArray.length > 0) {
  for (const item of parsedArray) {
    const idx = toNum(item.block_id);
    if (idx == null) continue;
    const b = blocks[idx];
    if (!b) continue;

    const line = resolveLine(b, item.line);
    if (line != null && item.comment) {
      pushUnique(comments, {
        path: b.path,
        line,
        side: 'RIGHT',
        body: String(item.comment)
      });
    }
  }
} else if (blocks.length > 0 && rawOutput) {
  // Fallback: один общий комментарий к первому блоку
  pushUnique(comments, {
    path: blocks[0].path,
    line: Number(blocks[0].line),
    side: 'RIGHT',
    body: rawOutput.slice(0, 500)
  });
}

return [{
  json: {
    review_payload: {
      event: 'COMMENT',
      body: `🤖 AI Code Review (${modelLabel}): точечных комментариев — ${comments.length}`,
      comments
    }
  }
}];
